"""P4 re-review probes for H1_r1 (swarm/broker). Isolated /tmp dirs only."""
import json, os, subprocess, sys, tempfile, time, traceback
from pathlib import Path

REPO = "~/Documentos/viewpoint-hackathon"
sys.path.insert(0, REPO)
for k in list(os.environ):
    if k.startswith("SWARM_"):
        del os.environ[k]
from swarm.broker import broker as B  # noqa: E402
from swarm.broker import bridge as BR  # noqa: E402

RESULTS = {}


def mkcfg(root: Path, **kw):
    return B.BrokerConfig(
        vision_mode=kw.pop("vision_mode", "mock"),
        inbox_dir=root / "inbox", outbox_dir=root / "outbox", rejected_dir=root / "rejected",
        frames_dir=root / "frames", intents_dir=root / "intents",
        events_log=root / "events.jsonl", nonce_file=root / "nonce.txt",
        poll_ms=10, **kw)


def events(root):
    return [json.loads(l) for l in (root / "events.jsonl").read_text().splitlines() if l.strip()]


def closes(root):
    return [e for e in events(root) if e.get("rec") == "close" and e.get("verdict") != "PASS"]


def put(root, agent, name, payload, raw=None):
    d = root / "intents" / agent
    d.mkdir(parents=True, exist_ok=True)
    p = d / name
    if raw is not None:
        p.write_bytes(raw)
    else:
        p.write_text(json.dumps(payload))
    return p


def base_intent(agent, eid, lane="script", **kw):
    d = {"v": 1, "event_id": eid, "agent_id": agent, "lane": lane, "lease_epoch": 1,
         "created_ts_ms": B.now_ms()}
    if lane == "script":
        d.update(write_set=["col:CHAR_x"] if agent == "modeler-agent" else ["cam:main"],
                 script="x = 1\n", script_sha256=None)
    d.update(kw)
    return d


def bridge_hook(root, exec_fn=None):
    def hook():
        BR.process_inbox_once(root / "inbox", root / "outbox", root / "rejected", root / "nonce.txt",
                              exec_fn=exec_fn or (lambda s, p: None))
    return hook


def probe(name):
    def deco(fn):
        root = Path(tempfile.mkdtemp(prefix=f"{name}_", dir="/tmp/p4_h1r1"))
        try:
            RESULTS[name] = fn(root)
        except BaseException as exc:  # noqa: BLE001
            RESULTS[name] = {"CRASH": f"{type(exc).__name__}: {exc}", "tb": traceback.format_exc()[-600:]}
        return fn
    return deco


# ---------------- B1 ----------------
@probe("B1_traversal")
def _(root):
    victim = root / "victim.py"
    victim.write_text("ORIGINAL = 1\n")
    b = B.SwarmBroker(mkcfg(root, script_timeout_s=0.2))
    bad_ids = ["../../../victim", "../victim", "a/b", "a\\b", "..", ".", "x..y", "", 123, None,
               "A" * 129, "-lead", ".hidden", "ok\n", "ok\x00z"]
    for i, eid in enumerate(bad_ids):
        put(root, "modeler-agent", f"bad{i:02d}.json", base_intent("modeler-agent", eid))
    b.step_sweep()
    b.close()
    out_of_inbox = [str(p) for p in root.rglob("*.py") if root / "inbox" not in p.parents]
    cs = closes(root)
    return {
        "victim": victim.read_text(), "victim_exists": victim.exists(),
        "closes": sorted({(c["verdict"], c["reason"]) for c in cs}),
        "n_closes": len(cs), "n_bad": len(bad_ids),
        "rejected_archive": len(list((root / "intents/modeler-agent/rejected").iterdir())),
        "py_outside_inbox": out_of_inbox,
        "inbox_files": [p.name for p in (root / "inbox").iterdir()],
    }


# ---------------- B2 ----------------
@probe("B2_poison_and_restart")
def _(root):
    put(root, "modeler-agent", "p_list.json", [1, 2, 3])
    put(root, "modeler-agent", "p_null_ts.json", base_intent("modeler-agent", "e_null", created_ts_ms=None))
    put(root, "modeler-agent", "p_str_ts.json", base_intent("modeler-agent", "e_str", created_ts_ms="abc"))
    put(root, "modeler-agent", "p_nan.json", None, raw=b'{"event_id":"e_nan","created_ts_ms":NaN}')
    put(root, "modeler-agent", "p_inf.json", None, raw=b'{"event_id":"e_inf","created_ts_ms":Infinity}')
    put(root, "modeler-agent", "p_noid.json", {k: v for k, v in base_intent("modeler-agent", "x").items() if k != "event_id"})
    put(root, "modeler-agent", "p_badjson.json", None, raw=b'{"event_id": ')
    put(root, "modeler-agent", "p_nonutf8.json", None, raw=b'\xff\xfe\x00{')
    put(root, "props-agent", "p_drops.json", base_intent("props-agent", "e_drops", _drops="zz"))
    put(root, "props-agent", "p_lane.json", base_intent("props-agent", "e_lane", lane=["gui"]))
    put(root, "props-agent", "p_ws.json", base_intent("props-agent", "e_ws", write_set="col:PROPS_"))
    put(root, "camera-agent", "p_keys.json", base_intent("camera-agent", "e_keys", lane="gui", keys="KP_1",
                                                          footprint=[0, 0, 10, 10], based_on_frame=0))
    put(root, "camera-agent", "p_fp.json", base_intent("camera-agent", "e_fp", lane="gui", keys=["KP_1"],
                                                        footprint=[0, 0, "a", True], based_on_frame="0"))
    put(root, "camera-agent", "p_cur.json", base_intent("camera-agent", "e_cur", lane="gui", keys=["KP_1"],
                                                         footprint=[0, 0, 10, 10], based_on_frame=0, cursor_xy={"a": 1}))
    put(root, "director-agent", "d_list.json", ["stop"])
    put(root, "director-agent", "d_badts.json", {"op": "resume", "created_ts_ms": "zz"})
    put(root, "director-agent", "d_badop.json", {"op": ["stop"], "agent_id": ["x"]})
    put(root, "director-agent", "d_badagent.json", {"op": "park", "agent_id": {"a": 1}})
    res = {}
    try:
        b = B.SwarmBroker(mkcfg(root, script_timeout_s=0.2), outbox_poll_hook=bridge_hook(root))
        for _ in range(4):
            b.step_sweep()
        res["state1"] = b.queue_state
        b.close()
    except BaseException as exc:  # noqa: BLE001
        res["run1_crash"] = f"{type(exc).__name__}: {exc}"
    left = sorted(p.name for d in (root / "intents").iterdir() for p in d.iterdir() if p.is_file())
    res["left_in_intent_dirs"] = left
    try:
        b2 = B.SwarmBroker(mkcfg(root, script_timeout_s=0.2))
        b2.step_sweep()
        b2.close()
        res["restart"] = "ok"
    except BaseException as exc:  # noqa: BLE001
        res["restart"] = f"CRASH {type(exc).__name__}: {exc}"
    res["verdicts"] = sorted({(c.get("event_id"), c["verdict"]) for c in closes(root)}, key=str)
    return res


@probe("B2_lone_surrogate")
def _(root):
    # Valid JSON (\\ud800 escape), valid event_id; agent-controlled string field carries a lone surrogate.
    raw = ('{"event_id":"e_sur","agent_id":"modeler-agent","lane":"script","lease_epoch":1,'
           '"kind":"\\ud800","write_set":["col:CHAR_x"],"script":"x=1\\n","created_ts_ms":1}').encode()
    put(root, "modeler-agent", "sur.json", None, raw=raw)
    res = {}
    b = B.SwarmBroker(mkcfg(root, script_timeout_s=0.2))
    try:
        b.step_sweep()
        res["run"] = "ok"
    except BaseException as exc:  # noqa: BLE001
        res["run"] = f"CRASH {type(exc).__name__}: {str(exc)[:120]}"
    b.close()
    res["file_left"] = (root / "intents/modeler-agent/sur.json").exists()
    res["archived_processed"] = (root / "intents/modeler-agent/processed/sur.json").exists()
    try:
        b2 = B.SwarmBroker(mkcfg(root, script_timeout_s=0.2))
        b2.step_sweep()
        b2.close()
        res["restart"] = "ok"
    except BaseException as exc:  # noqa: BLE001
        res["restart"] = f"CRASH {type(exc).__name__}"
    return res


@probe("B2_outbox_nondict")
def _(root):
    b = B.SwarmBroker(mkcfg(root, script_timeout_s=2.0))

    def hook():
        for p in (root / "inbox").glob("*.py"):
            (root / "outbox" / (p.stem + ".json")).write_text("[1,2]")
            p.unlink()
    b._outbox_poll_hook = hook
    put(root, "modeler-agent", "e1.json", base_intent("modeler-agent", "e1"))
    b.step_sweep()
    b.close()
    return {"state": b.queue_state, "verdicts": [(c["event_id"], c["verdict"], c["reason"]) for c in closes(root)]}


# ---------------- M1 ----------------
@probe("M1_rebased_drops")
def _(root):
    b = B.SwarmBroker(mkcfg(root))
    b.capture_frame(); b.capture_frame()  # head=2
    put(root, "camera-agent", "r.json", base_intent("camera-agent", "e_reb", lane="gui", keys=["KP_1"],
                                                     footprint=[0, 80, 1580, 900], based_on_frame=0,
                                                     rebased=True, _rebased=True))
    put(root, "camera-agent", "d.json", base_intent("camera-agent", "e_drp", lane="gui", keys=["KP_1"],
                                                     footprint=[0, 80, 1580, 900], based_on_frame=0,
                                                     _drops=-50, drops=-50, created_ts_ms=B.now_ms() + 1))
    for _ in range(8):
        b.step_sweep()
    b.close()
    return {"closes": [(c["event_id"], c["verdict"], c["drops"], c["rebased"]) for c in closes(root)],
            "parks": [e for e in events(root) if e.get("rec") == "control" and e.get("op") == "park"].__len__(),
            "fifo_left": len(b.fifos["camera-agent"])}


# ---------------- live GUI paths ----------------
def fake_vision(root, plan):
    """plan: dict key -> rc or 'timeout'; 'hover' for --xy; 'look' -> 'fail' or ok."""
    src = root / "src.png"
    from PIL import Image
    Image.new("RGB", (1920, 1080), (1, 2, 3)).save(src)
    calls = []

    def runner(cmd, timeout_s):
        args = cmd[3:]
        calls.append(args)
        if args[0] == "look":
            if plan.get("look_fail_after") is not None and sum(1 for c in calls if c[0] == "look") > plan["look_fail_after"]:
                return subprocess.CompletedProcess(cmd, 1, "", "boom")
            return subprocess.CompletedProcess(cmd, 0, json.dumps({"frame": str(src)}), "")
        if "--xy" in args:
            r = plan.get("hover", 0)
        else:
            r = plan.get(args[args.index("--key") + 1], 0)
        if r == "timeout":
            raise subprocess.TimeoutExpired(cmd, timeout_s)
        out = json.dumps({"changed_regions": [[100, 100, 50, 50]]}) if r == 0 else "{}"
        return subprocess.CompletedProcess(cmd, r, out, "")
    return runner, calls


def gui_case(root, plan, keys, vision_mode="mock"):
    runner, calls = fake_vision(root, plan)
    b = B.SwarmBroker(mkcfg(root, vision_mode=vision_mode), vision_runner=runner)
    put(root, "camera-agent", "g.json", base_intent("camera-agent", "g1", lane="gui", keys=keys,
                                                     footprint=[0, 80, 1580, 900], based_on_frame=b.head_frame))
    b.step_sweep()
    b.close()
    c = closes(root)
    return {"verdict": [(x["verdict"], x["reason"]) for x in c], "view_epoch": b.view_epoch,
            "queue_state": b.queue_state, "tick": b.tick, "head": b.head_frame,
            "acts": [a for a in calls if a[0] == "act"].__len__()}


@probe("m2_hover_rc3")
def _(root):
    return gui_case(root, {"hover": 3, "KP_1": 0}, ["KP_1"])


@probe("M4_mixed_rc0_rc3")
def _(root):
    return gui_case(root, {"KP_1": 0, "KP_3": 3}, ["KP_1", "KP_3"])


@probe("M4_rc3_then_rc0")
def _(root):
    return gui_case(root, {"KP_3": 3, "KP_1": 0}, ["KP_3", "KP_1"])


@probe("M3_mid_key_timeout")
def _(root):
    return gui_case(root, {"KP_1": 0, "KP_3": "timeout"}, ["KP_1", "KP_3"])


@probe("M8_gui_look_fail_live")
def _(root):
    return gui_case(root, {"KP_1": 0, "look_fail_after": 1}, ["KP_1"], vision_mode="live")


@probe("M8_script_look_fail_live")
def _(root):
    runner, _calls = fake_vision(root, {"look_fail_after": 1})
    b = B.SwarmBroker(mkcfg(root, vision_mode="live", script_timeout_s=3.0), vision_runner=runner,
                      outbox_poll_hook=bridge_hook(root))
    put(root, "modeler-agent", "s.json", base_intent("modeler-agent", "s1"))
    b.step_sweep()
    b.close()
    return {"verdict": [(x["verdict"], x["reason"][:60]) for x in closes(root)], "state": b.queue_state,
            "scene_epoch": b.scene_epoch}


# ---------------- M2 ----------------
@probe("M2_script_timeout")
def _(root):
    b = B.SwarmBroker(mkcfg(root, script_timeout_s=0.3))
    put(root, "modeler-agent", "t1.json", base_intent("modeler-agent", "t1"))
    b.step_sweep()
    r = {"after_timeout": (b.queue_state, b.actuator_busy, b.tick),
         "inbox_left": [p.name for p in (root / "inbox").iterdir()]}
    # director resume (not reconcile) -> IDLE but actuator still busy
    put(root, "director-agent", "c1.json", {"op": "resume", "created_ts_ms": 1})
    put(root, "props-agent", "t2.json", base_intent("props-agent", "t2", write_set=["col:PROPS_a"]))
    b.step_sweep()
    r["after_resume"] = (b.queue_state, b.actuator_busy)
    put(root, "director-agent", "c2.json", {"op": "reconcile", "created_ts_ms": 2})
    b.step_sweep()
    r["after_reconcile"] = (b.queue_state, b.actuator_busy)
    b.close()
    r["verdicts"] = [(c["event_id"], c["verdict"], c["tick"]) for c in closes(root)]
    return r


# ---------------- events.jsonl append-only ----------------
@probe("EV_append_only")
def _(root):
    ev = root / "events.jsonl"
    ev.write_text('{"v":1,"rec":"sentinel"}\n')
    prefix = ev.read_bytes()
    sizes = []
    orig = B.SwarmBroker._emit_event

    def spy(self, rec):
        orig(self, rec)
        sizes.append(ev.stat().st_size)
    B.SwarmBroker._emit_event = spy
    try:
        b = B.SwarmBroker(mkcfg(root, script_timeout_s=2.0), outbox_poll_hook=bridge_hook(root))
        for i in range(3):
            put(root, "modeler-agent", f"a{i}.json", base_intent("modeler-agent", f"a{i}", created_ts_ms=i))
        for _ in range(4):
            b.step_sweep()
        b.close()
        b2 = B.SwarmBroker(mkcfg(root, script_timeout_s=2.0))  # restart same log
        b2.close()
    finally:
        B.SwarmBroker._emit_event = orig
    data = ev.read_bytes()
    return {"prefix_kept": data.startswith(prefix), "monotonic": all(x < y for x, y in zip(sizes, sizes[1:])),
            "n_emits": len(sizes), "all_lines_json": all(json.loads(l) for l in data.splitlines())}


@probe("LOCK_second_broker")
def _(root):
    b = B.SwarmBroker(mkcfg(root))
    try:
        B.SwarmBroker(mkcfg(root))
        r = "second broker started (no lock)"
    except RuntimeError as exc:
        r = f"refused: {exc}"[:90]
    b.close()
    return r


for k, v in RESULTS.items():
    print(f"== {k}")
    print(json.dumps(v, indent=1, default=str)[:2500])

